import{c as n,Q as s,j as a,m as t}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"DeQue","description":"","frontmatter":{},"headers":[{"level":1,"title":"DeQue","slug":"deque"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TQue/DeQue.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TQue/DeQue.md"}'),l={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TQue/DeQue.md"};function p(i,e,o,d,r,c){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="deque" tabindex="-1">DeQue <a class="header-anchor" href="#deque" aria-label="Permalink to &quot;DeQue&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将Tensor从队列中取出，用于后续处理。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>无需指定源和目的位置</p><ul><li><p>non-inplace接口：将入队的LocalTensor地址从队列中取出赋值给新创建的Tensor并返回</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline LocalTensor&lt;T&gt; DeQue()</span></span></code></pre></div></li><li><p>inplace接口：通过出参的方式返回，可以减少Tensor反复创建的开销，具体使用指导可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E9%99%84%E5%BD%95/%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C/%E5%A6%82%E4%BD%95%E4%BD%BF%E7%94%A8Tensor%E5%8E%9F%E5%9C%B0%E6%93%8D%E4%BD%9C%E6%8F%90%E5%8D%87%E7%AE%97%E5%AD%90%E6%80%A7%E8%83%BD.md" target="_blank" rel="noreferrer">Tensor原地操作</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void DeQue(LocalTensor&lt;T&gt;&amp; tensor)</span></span></code></pre></div></li></ul></li><li><p>需要指定源和目的位置</p><p>通过<a href="./../TQueBind/TQueBind.html">TQueBind</a>绑定VECIN和VECOUT可实现VECIN和VECOUT内存复用，如下接口用于存在Vector计算的场景下实现复用，在出队时需要指定源和目的位置；不存在Vector计算的场景下可直接调用LocalTensor&lt;T&gt; DeQue()出队接口。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition srcUserPos, TPosition dstUserPos, typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline LocalTensor&lt;T&gt; DeQue()</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>说明</th></tr></thead><tbody><tr><td>T</td><td>Tensor的数据类型。</td></tr><tr><td>srcUserPos</td><td>用户指定队列的src position，当前只支持如下通路：GM-&gt;VECIN/VECOUT-&gt;GM。</td></tr><tr><td>dstUserPos</td><td>用户指定队列的dst position，当前只支持如下通路：GM-&gt;VECIN/VECOUT-&gt;GM。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>tensor</td><td>输出</td><td>inplace接口需要通过出参的方式返回Tensor。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>对空队列执行DeQue是一种异常行为，会在CPU调测时报错。</li><li>non-inplace接口和指定源和目的位置的接口，需要将TQueBind的depth模板参数设置为非零值；inplace接口，需要将TQueBind的depth模板参数设置为0。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>non-inplace接口和指定源和目的位置的接口返回值为从队列中取出的<a href="./../../../../基础数据结构/LocalTensor/LocalTensor.html">LocalTensor</a>；inplace接口没有返回值。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 接口: DeQue Tensor</span></span>
<span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECOUT, 4&gt; que;</span></span>
<span class="line"><span>int num = 4;</span></span>
<span class="line"><span>int len = 1024;</span></span>
<span class="line"><span>pipe.InitBuffer(que, num, len);</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; tensor1 = que.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>que.EnQue(tensor1);</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; tensor2 = que.DeQue&lt;half&gt;(); // 将tensor从VECOUT的Queue中搬出</span></span>
<span class="line"><span>// 接口: DeQue Tensor，指定特定的Src/Dst position</span></span>
<span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TQueBind&lt;AscendC::TPosition::VECIN, AscendC::TPosition::VECOUT, 1&gt; que;</span></span>
<span class="line"><span>int num = 4;</span></span>
<span class="line"><span>int len = 1024;</span></span>
<span class="line"><span>pipe.InitBuffer(que, num, len);</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; tensor1 = que.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>que.EnQue&lt;AscendC::TPosition::GM, AscendC::TPosition::VECIN, half&gt;(tensor1);</span></span>
<span class="line"><span>// 将tensor从VECIN的Queue中搬出</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; tensor2 = que.DeQue&lt;AscendC::TPosition::GM, AscendC::TPosition::VECIN, half&gt;(); </span></span>
<span class="line"><span>// inplace接口</span></span>
<span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECOUT, 0&gt; que;</span></span>
<span class="line"><span>int num = 2;</span></span>
<span class="line"><span>int len = 1024;</span></span>
<span class="line"><span>pipe.InitBuffer(que, num, len);</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; tensor1;</span></span>
<span class="line"><span>que.AllocTensor&lt;half&gt;(tensor1);</span></span>
<span class="line"><span>que.EnQue(tensor1);</span></span>
<span class="line"><span>que.DeQue&lt;half&gt;(tensor1); // 将tensor从VECOUT的Queue中搬出</span></span>
<span class="line"><span>que.FreeTensor&lt;half&gt;(tensor1);</span></span></code></pre></div>`,18)])])}const T=n(l,[["render",p]]);export{h as __pageData,T as default};
